-- SELECT only. Run after apply. 읽기 전용 역할에서 돈다(카탈로그·기록·줄 수만 읽음, 줄 내용 없음).
-- 적용 뒤 기대: 예/아니오 항목은 모두 예. 줄 수·해시는 사전 확인 기록과 같은 값.
-- expect: history row present = 예
-- expect: new tables RLS on, no anon or PUBLIC privilege = 예
-- expect: articles: authenticated read only, server writes = 예
-- expect: marks: owner policy, keywords server only = 예
-- expect: articles policies: readers and operator scrap only = 예
-- expect: functions definer, fixed search_path, execute as planned = 예
-- expect: rooms news_at nullable, no screen write, none set = 예
-- expect: articles copied once per url key, operator ids kept = 예
-- expect: marks copied = 예
-- expect: items rows = 기록
-- expect: distinct url keys = 기록
-- expect: marked item rows = 기록
-- expect: rooms rows = 기록
-- expect: rooms grants policies triggers hash = 기록
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261115100000' and name='news_for_all')=1 then '예' else '아니오' end as value
union all select 'new tables RLS on, no anon or PUBLIC privilege',case when (select count(*) from pg_class where oid in (to_regclass('public.app_news_articles'),to_regclass('public.app_news_marks')) and relrowsecurity and coalesce(relacl::text,'') !~ '(^|[{,])(anon)?=')=2 and not has_any_column_privilege('anon','public.app_news_articles','select,insert,update,references') and not has_any_column_privilege('anon','public.app_news_marks','select,insert,update,references') and not has_table_privilege('anon','public.app_news_articles','delete') and not has_table_privilege('anon','public.app_news_marks','delete') then '예' else '아니오' end
union all select 'articles: authenticated read only, server writes',case when has_table_privilege('authenticated','public.app_news_articles','select') and not has_any_column_privilege('authenticated','public.app_news_articles','insert,update') and not has_table_privilege('authenticated','public.app_news_articles','delete,truncate') and has_table_privilege('service_role','public.app_news_articles','select,insert,update,delete') then '예' else '아니오' end
union all select 'marks: owner policy, keywords server only',case when (select count(*) from pg_policy where polrelid=to_regclass('public.app_news_marks') and polroles=array['authenticated'::regrole]::oid[] and polcmd='*' and pg_get_expr(polqual,polrelid) like '%app_is_workspace_owner(workspace_id)%')=1 and (select count(*) from pg_policy where polrelid=to_regclass('public.app_news_marks'))=1 and not has_column_privilege('authenticated','public.app_news_marks','keywords','insert,update') and has_column_privilege('authenticated','public.app_news_marks','starred_at','insert,update') and has_table_privilege('authenticated','public.app_news_marks','select,delete') then '예' else '아니오' end
union all select 'articles policies: readers and operator scrap only',case when (select count(*) from pg_policy where polrelid=to_regclass('public.app_news_articles'))=2 and (select count(*) from pg_policy where polrelid=to_regclass('public.app_news_articles') and polcmd='r' and polpermissive and polroles=array['authenticated'::regrole]::oid[] and (pg_get_expr(polqual,polrelid) like '%app_news_reader_ok()%' or pg_get_expr(polqual,polrelid) like '%app_news_scrap_reader_ok()%'))=2 then '예' else '아니오' end
union all select 'functions definer, fixed search_path, execute as planned',case when (select count(*) from pg_proc where oid in (to_regprocedure('private.app_news_reader_ok()'),to_regprocedure('private.app_news_scrap_reader_ok()'),to_regprocedure('public.app_feed_room_news(text,boolean)'),to_regprocedure('public.app_news_room_take(uuid,text,jsonb)')) and prosecdef and proconfig=array['search_path=""'] and coalesce(proacl::text,'') !~ '(^|[{,])=')=4 and has_function_privilege('authenticated','public.app_feed_room_news(text,boolean)','execute') and not has_function_privilege('anon','public.app_feed_room_news(text,boolean)','execute') and not has_function_privilege('service_role','public.app_feed_room_news(text,boolean)','execute') and has_function_privilege('service_role','public.app_news_room_take(uuid,text,jsonb)','execute') and not has_function_privilege('authenticated','public.app_news_room_take(uuid,text,jsonb)','execute') and not has_function_privilege('anon','public.app_news_room_take(uuid,text,jsonb)','execute') then '예' else '아니오' end
union all select 'rooms news_at nullable, no screen write, none set',case when exists(select 1 from pg_attribute where attrelid=to_regclass('public.app_feed_rooms') and attname='news_at' and not attisdropped and atttypid='timestamptz'::regtype and not attnotnull) and not has_column_privilege('authenticated','public.app_feed_rooms','news_at','insert,update') and not exists(select 1 from public.app_feed_rooms where news_at is not null) then '예' else '아니오' end
union all select 'articles copied once per url key, operator ids kept',case when (select count(*) from public.app_news_articles)=(select count(distinct url_key) from public.app_news_items) and not exists(select 1 from public.app_news_items i where i.workspace_id in (select workspace_id from public.app_operator_features where feature='telegram') and not exists(select 1 from public.app_news_articles a where a.id=i.id)) then '예' else '아니오' end
union all select 'marks copied',case when (select count(*) from public.app_news_marks)=(select count(*) from public.app_news_items where starred_at is not null or folder_id is not null or hidden_at is not null or cardinality(keywords)>0) then '예' else '아니오' end
union all select 'items rows',(select count(*)::text from public.app_news_items)
union all select 'distinct url keys',(select count(distinct url_key)::text from public.app_news_items)
union all select 'marked item rows',(select count(*)::text from public.app_news_items where starred_at is not null or folder_id is not null or hidden_at is not null or cardinality(keywords)>0)
union all select 'rooms rows',(select count(*)::text from public.app_feed_rooms)
union all select 'rooms grants policies triggers hash',md5(coalesce((select c.relrowsecurity::text||':'||coalesce(c.relacl::text,'') from pg_class c where c.oid=to_regclass('public.app_feed_rooms')),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid=to_regclass('public.app_feed_rooms')),'')
  ||coalesce((select string_agg(t.tgname::text||':'||t.tgenabled::text||':'||t.tgfoid::regproc::text,',' order by t.tgname) from pg_trigger t where t.tgrelid=to_regclass('public.app_feed_rooms') and not t.tgisinternal),''));
